import{_ as r,l as s,o as e,c as o,v as i,p as l,x as t,d as E,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"东亚危机","description":"","frontmatter":{"title":"东亚危机","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/east-asian-crisis.md","filePath":"econ/east-asian-crisis.md","lastUpdated":1789023840000}'),h={name:"econ/east-asian-crisis.md"};function c(m,a,A,_,B,u){const n=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=i('<h1 id="东亚危机" tabindex="-1">东亚危机 <a class="header-anchor" href="#东亚危机" aria-label="Permalink to &quot;东亚危机&quot;">​</a></h1><div class="epigraph"><p>钉住加短期外币债，把流动性错配写成可交易的攻击对象。基本面可以有漏洞，恐慌可以把能滚的债变成不能滚——第三代危机是资产负债表，不是「亚洲价值观」。</p><footer>—— Krugman 与第三代危机模型；Corsetti, Pesenti and Roubini 的东亚诊断；Kaminsky and Reinhart 孪生危机；对照 Eichengreen；原罪文献</footer></div><p><a href="/econ/stagflation-1970s">上一课</a>是中心国家的通胀定锚失败。本课换新兴市场 1997–98：泰国、印尼、韩国等在增长纪录上不像第一代「财政崩了就贬」的剧本，却在几周内失掉平价与信用。缺口是原罪与期限：本币不能在国际上借长期，企业与银行借短美元、资产是本币长项目；钉住把汇率风险藏进表，直到平价一破，净值同时蒸发。后课 2008 把类似的批发挤兑搬到中心国家影子银行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一代：储备对财政赤字，缓慢见底。第二代：多重均衡，攻击因预期而自实现。东亚更像第三代：公司与银行的外币短债，房地产与出口应收为资产，政府或明或暗担保。钉住鼓励不套期。一旦出口或资产价格动摇，展期停止，储备既要保平价又要救银行，两者不能兼得。缺口不是列 Soros 或哪一天弃钉，而是：<strong>固定汇率加外币短债 = 没有独立的最后贷款人</strong>——本币印出来换不到美元。这与<a href="/econ/dollar-swap-lines">美元互换线</a>课的批发美元荒是亲戚，层级在新兴市场银行。</p><p>孪生危机：货币崩溃与银行崩溃一起出现，Kaminsky–Reinhart 的经验规则在此贴合。</p><h3 id="不是「亚洲价值观」崩溃" tabindex="-1">不是「亚洲价值观」崩溃 <a class="header-anchor" href="#不是「亚洲价值观」崩溃" aria-label="Permalink to &quot;不是「亚洲价值观」崩溃&quot;">​</a></h3><p>把危机写成文化或裙带的道德剧，会漏掉可迁移的资产负债表。裙带可以解释事前杠杆，不能解释为何这么多国家同一季度爆。国际流动性与共同债权人收缩，是传导。IMF 条件争议是政策史，机制仍是展期与净值。</p><p><span class="marginnote">Corsetti–Pesenti–Roubini 强调或有财政：私人外币债在担保下是隐性主权债。主权可持续课的 \\(b\\) 被低估，直到危机把它显化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三句。(1) 钉住：三角牺牲独立 \\(M\\)，在资本流入时尤其脆。(2) 原罪：不能用本币借外债，货币错配。(3) 短债：流动性错配，挤兑逻辑与银行相同。政策实验：弃钉后谁有外币流动性谁先稳；资本管制与国际救助是替代的展期安排。不要用「基本面很好所以只是恐慌」或「基本面很差所以只是惩罚」单选：两者可以叠，恐慌放大漏洞。公司部门的外汇敞口表，比 GDP 增长率更能预测谁先爆——这是第三代的可观测矩。</p>',11)),(e(),l(p,null,{default:t(()=>[d(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAG%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E4%B8%AD%E5%BF%83%E9%80%9A%E8%83%80%E9%94%9A%22%5D%20--%3E%20PEG%5B%22%E9%92%89%E4%BD%8F%E5%8A%A0%E7%9F%AD%E7%BE%8E%E5%85%83%E5%80%BA%22%5D%0A%20%20PEG%20--%3E%20MM%5B%22%E8%B4%A7%E5%B8%81%E4%B8%8E%E6%9C%9F%E9%99%90%E5%8F%8C%E9%94%99%E9%85%8D%22%5D%0A%20%20MM%20--%3E%20RUN%5B%22%E5%B1%95%E6%9C%9F%E5%81%9C%E6%AD%A2%2C%20%E5%87%80%E5%80%BC%E8%92%B8%E5%8F%91%22%5D%0A%20%20RUN%20--%3E%20GFC%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E4%B8%AD%E5%BF%83%E5%BD%B1%E5%AD%90%E9%93%B6%E8%A1%8C%E6%8C%A4%E5%85%91%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>不要把股权组合投资的撤退与银行短债的不展期当成同一流动性。后者是危机核。股权下跌伤净值，但不自动触发必须用美元偿还的到期墙；短债不展期是墙上的砖同时到期。政策若用提高利率保卫平价，国内加速器更狠——与金本位保卫平价是同族工具，对象换成了原罪债。套期比率是可观测的政策目标，增长率不是。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是未套期的期权：平价是政府卖出的廉价保险，企业乐于借美元。平价破，保险行权，净值为负，投资中断，汇率超调。银行担保把私人亏损并入主权，利差跳升，多重均衡打开——与主权课同一句，货币从本币换成外币。金本位输出通缩；东亚输出的是突然停止与进口压缩。滞胀是供给加弱锚；东亚是金融加钉住。</p><p>与 IO 无关，也不进限价簿。救援与道德风险：事前担保鼓励错配，事后不救则加速器更狠——时间一致性，接到最后一课央行与财政边界。资本管制可以拉长展期，代价是事后的配置扭曲；它改变的是攻击速度，不自动修好货币错配。</p><p><span class="marginnote">Krugman 的第三代把危机写成资产价格与资产负债表的循环，而不是商品市场的储备算术。本课用这张图组织，不重推全部微分方程。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供做空钉住货币的任何操作步骤。不把每次评级下调编年。2008 的中心国家版本下一课：抵押品与批发融资替代了「外币」，但挤兑同构。后课默认：东亚用钉住 × 原罪 × 短债来读；文化叙事不当主因果。金本位、布雷顿、滞胀、东亚，是约束形态的序列，不是年代目录。公司部门未套期的美元债，是原罪在企业表上的位置；主权若再担保，两张表并成一张。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>第三代危机核是外币短债加钉住，不是财政第一代剧本。</li><li>平价是廉价保险，破钉使净值同时蒸发。</li><li>孪生危机：银行与货币一起倒，隐性主权债显化。</li><li>恐慌与漏洞可叠加；不要单选道德剧。</li><li>保平价的加息会经国内加速器加深衰退，与金本位同族。</li><li>出处：Krugman；Corsetti, Pesenti and Roubini；Kaminsky and Reinhart；Eichengreen。</li></ul>',9))])}const C=r(h,[["render",c]]);export{b as __pageData,C as default};
